#include <ctype.h>
#include <errno.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>

static int parse_int(const char *text, int *result) {
    char *end = NULL;
    long value;

    if (text == NULL || result == NULL) {
        return 0;
    }
    errno = 0;
    value = strtol(text, &end, 10);
    if (end == text || errno == ERANGE) {
        return 0;
    }
    while (*end != '\0' && isspace((unsigned char)*end)) {
        ++end;
    }
    if (*end != '\0' || value < INT_MIN || value > INT_MAX) {
        return 0;
    }
    *result = (int)value;
    return 1;
}

int main(void) {
    const char input[] = " 123 \n";
    int parsed = 0;

    if (!parse_int(input, &parsed)) {
        puts("invalid integer");
        return 1;
    }
    printf("parsed=%d\n", parsed);
    return 0;
}

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

static int append_int(int **items, size_t *count, size_t *capacity, int value) {
    size_t new_capacity;
    int *grown;

    if (items == NULL || count == NULL || capacity == NULL ||
        *count > *capacity || (*capacity > 0 && *items == NULL)) {
        return 0;
    }
    if (*count == *capacity) {
        if (*capacity == 0) {
            new_capacity = 4;
        } else {
            if (*capacity > SIZE_MAX / 2) {
                return 0;
            }
            new_capacity = *capacity * 2;
        }
        if (new_capacity > SIZE_MAX / sizeof **items) {
            return 0;
        }
        grown = realloc(*items, new_capacity * sizeof **items);
        if (grown == NULL) {
            return 0;
        }
        *items = grown;
        *capacity = new_capacity;
    }
    (*items)[*count] = value;
    ++*count;
    return 1;
}

int main(void) {
    int *values = NULL;
    size_t count = 0;
    size_t capacity = 0;
    size_t i;

    if (!append_int(&values, &count, &capacity, 10) ||
        !append_int(&values, &count, &capacity, 20) ||
        !append_int(&values, &count, &capacity, 30)) {
        free(values);
        fputs("unable to append value\n", stderr);
        return 1;
    }
    for (i = 0; i < count; ++i) {
        printf("%s%d", i == 0 ? "values=" : ",", values[i]);
    }
    putchar('\n');
    free(values);
    return 0;
}
